// Helper functions for tooltips
export const getSourceByCodename = (codename, sources) => {
  return sources.find(source => source.codename === codename);
};

export const getAirlineName = (codename, airlines) => {
  const airline = airlines.find(airline => airline.code === codename);
  return airline ? airline.name : codename;
};

export const formatMileageCost = (cost) => {
  return Number(cost).toLocaleString();
};

export const formatTaxes = (taxes, currency) => {
  return taxes ? `${Number(taxes).toLocaleString()} ${currency}` : 'N/A';
};

export const createEnhancedTooltip = (classCode, flights, route, dateString, sources, airlines) => {
  if (!flights || flights.length === 0) return null;

  const tooltip = document.createElement('div');
  tooltip.className = 'flight-tooltip';
  tooltip.id = `tooltip-${route}-${dateString}-${classCode}`;
  tooltip.style.position = 'absolute';
  tooltip.style.zIndex = '1000';
  tooltip.style.backgroundColor = 'white';
  tooltip.style.border = '1px solid #ccc';
  tooltip.style.borderRadius = '4px';
  tooltip.style.padding = '10px';
  tooltip.style.boxShadow = '0 2px 8px rgba(0, 0, 0, 0.15)';
  tooltip.style.maxHeight = '300px';
  tooltip.style.overflowY = 'auto';
  tooltip.style.maxWidth = '400px';

  const content = document.createElement('div');

  // Create title
  const title = document.createElement('h3');
  title.textContent = `${route} - ${dateString} - Class ${classCode}`;
  title.style.marginTop = '0';
  title.style.borderBottom = '1px solid #eee';
  title.style.paddingBottom = '5px';
  content.appendChild(title);

  // Add flight details
  flights.forEach((flight, index) => {
    const flightDiv = document.createElement('div');
    flightDiv.style.marginBottom = '10px';
    flightDiv.style.paddingBottom = '10px';
    flightDiv.style.borderBottom = index < flights.length - 1 ? '1px dashed #eee' : 'none';

    const flightSource = flight.rawData?.source;
    const source = flightSource ? getSourceByCodename(flightSource, sources) : null;

    // Add source info
    if (source) {
      const sourceDiv = document.createElement('div');
      sourceDiv.style.fontWeight = 'bold';
      sourceDiv.textContent = `${source.airline} ${source.ffname}`;
      flightDiv.appendChild(sourceDiv);
    }

    // Add airlines
    const airlinesText = flight.rawData?.[`${classCode}Airlines`] || '';
    if (airlinesText) {
      const airlinesDiv = document.createElement('div');
      airlinesDiv.textContent = `Airlines: ${airlinesText}`;
      flightDiv.appendChild(airlinesDiv);
    }

    // Add mileage cost
    const mileageCost = flight.rawData?.[`${classCode}MileageCost`];
    if (mileageCost && mileageCost !== '0') {
      const costDiv = document.createElement('div');
      costDiv.textContent = `Miles: ${formatMileageCost(mileageCost)}`;
      flightDiv.appendChild(costDiv);
    }

    // Add taxes
    const taxes = flight.rawData?.[`${classCode}TotalTaxes`];
    const currency = flight.rawData?.TaxesCurrency || 'USD';
    if (taxes && taxes !== 0) {
      const taxesDiv = document.createElement('div');
      taxesDiv.textContent = `Taxes: ${formatTaxes(taxes, currency)}`;
      flightDiv.appendChild(taxesDiv);
    }

    // Add direct info
    const isDirect = flight.rawData?.[`${classCode}Direct`];
    if (isDirect) {
      const directDiv = document.createElement('div');
      directDiv.textContent = 'Direct flight available';
      directDiv.style.color = 'green';
      flightDiv.appendChild(directDiv);
    }

    content.appendChild(flightDiv);
  });

  tooltip.appendChild(content);
  document.body.appendChild(tooltip);

  return tooltip;
};
